DROP PROCEDURE IF EXISTS `import_staging_children`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `import_staging_children` ()   BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE v_child_import_id INT;
    DECLARE v_household_id INT;
    DECLARE v_first_name VARCHAR(45);
    DECLARE v_last_name VARCHAR(45);
    DECLARE v_gender VARCHAR(20);
    DECLARE v_dob DATE;
    DECLARE v_sex_id INT;

    DECLARE child_cursor CURSOR FOR
        SELECT
            sci.child_import_id,
            mother.household_id,
            sci.normalized_child_first_name,
            sci.normalized_child_last_name,
            sci.gender,
            sci.date_of_birth
        FROM staging_child_mother_map scm
        JOIN staging_children_import sci
            ON sci.child_import_id = scm.child_import_id
        JOIN staging_resident_map srm
            ON srm.staging_id = scm.mother_staging_id
        JOIN resident mother
            ON mother.resident_id = srm.resident_id
        WHERE mother.household_id IS NOT NULL
          AND NOT EXISTS (
              SELECT 1
              FROM staging_child_resident_map crm
              WHERE crm.child_import_id = sci.child_import_id
          )
        ORDER BY sci.child_import_id;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    OPEN child_cursor;

    child_loop: LOOP
        FETCH child_cursor INTO
            v_child_import_id,
            v_household_id,
            v_first_name,
            v_last_name,
            v_gender,
            v_dob;

        IF done = 1 THEN
            LEAVE child_loop;
        END IF;

        SET v_sex_id = CASE
            WHEN UPPER(TRIM(v_gender)) = 'M' THEN 1
            WHEN UPPER(TRIM(v_gender)) = 'F' THEN 2
            ELSE NULL
        END;

            last_name,
            first_name,
            middle_name,
            relationship_to_hh_id,
            sex_id,
            date_of_birth,
            household_id
        )
        VALUES (
            TRIM(v_last_name),
            TRIM(v_first_name),
            NULL,
            NULL,
            v_sex_id,
            v_dob,
            v_household_id
        );

            child_import_id,
            resident_id
        )
        VALUES (
            v_child_import_id,
            LAST_INSERT_ID()
        );
    END LOOP;

    CLOSE child_cursor;
END$$

DROP PROCEDURE IF EXISTS `import_staging_residents`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `import_staging_residents` ()   BEGIN
    DECLARE done INT DEFAULT 0;
    DECLARE v_staging_id INT;
    DECLARE v_household_id INT;
    DECLARE v_first_name VARCHAR(45);
    DECLARE v_middle_name VARCHAR(45);
    DECLARE v_last_name VARCHAR(45);
    DECLARE v_relationship_id INT;
    DECLARE v_sex_id INT;
    DECLARE v_dob DATE;
    DECLARE v_religion_id INT;
    DECLARE v_ethnicity_id INT;
    DECLARE v_marital_status_id INT;

    DECLARE resident_cursor CURSOR FOR
        SELECT
            sr.staging_id,
            shm.household_id,
            TRIM(sr.normalized_first_name),
            NULLIF(TRIM(sr.normalized_middle_name), ''),
            TRIM(sr.normalized_last_name),
            sr.normalized_relationship_id,
            sr.normalized_sex_id,
            sr.normalized_date_of_birth,
            sr.normalized_religion_id,
            sr.normalized_ethnicity_id,
            sr.normalized_marital_status_id
        FROM staging_residents sr
        JOIN street st
          ON UPPER(REPLACE(TRIM(st.street_name), ' ', ''))
           = UPPER(REPLACE(TRIM(sr.street), ' ', ''))
        JOIN staging_household_map shm
          ON shm.normalized_house_number = sr.normalized_house_number
         AND shm.street_id = st.street_id
        JOIN household h
          ON h.household_id = shm.household_id
        WHERE sr.normalized_first_name IS NOT NULL
          AND TRIM(sr.normalized_first_name) <> ''
          AND sr.normalized_last_name IS NOT NULL
          AND TRIM(sr.normalized_last_name) <> ''
        ORDER BY sr.staging_id;

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    START TRANSACTION;

    OPEN resident_cursor;

    resident_loop: LOOP
        FETCH resident_cursor INTO
            v_staging_id,
            v_household_id,
            v_first_name,
            v_middle_name,
            v_last_name,
            v_relationship_id,
            v_sex_id,
            v_dob,
            v_religion_id,
            v_ethnicity_id,
            v_marital_status_id;

        IF done = 1 THEN
            LEAVE resident_loop;
        END IF;

            last_name,
            first_name,
            middle_name,
            relationship_to_hh_id,
            sex_id,
            date_of_birth,
            religion_id,
            ethnicity_id,
            marital_status_id,
            household_id
        )
        VALUES (
            v_last_name,
            v_first_name,
            v_middle_name,
            v_relationship_id,
            v_sex_id,
            v_dob,
            v_religion_id,
            v_ethnicity_id,
            v_marital_status_id,
            v_household_id
        );

            staging_id,
            resident_id
        )
        VALUES (
            v_staging_id,
            LAST_INSERT_ID()
        );
    END LOOP;

    CLOSE resident_cursor;

    COMMIT;
END$$

--
-- Functions
