DROP FUNCTION IF EXISTS `ProperCase`$$
CREATE DEFINER=`root`@`localhost` FUNCTION `ProperCase` (`input_text` VARCHAR(255)) RETURNS VARCHAR(255) CHARSET utf8mb4 DETERMINISTIC BEGIN
    DECLARE result_text VARCHAR(255) DEFAULT '';
    DECLARE word_text VARCHAR(255);
    DECLARE remaining_text VARCHAR(255);
    DECLARE space_pos INT;

    SET remaining_text = LOWER(TRIM(input_text));

    WHILE remaining_text <> '' DO
        SET space_pos = LOCATE(' ', remaining_text);

        IF space_pos = 0 THEN
            SET word_text = remaining_text;
            SET remaining_text = '';
        ELSE
            SET word_text = LEFT(remaining_text, space_pos - 1);
            SET remaining_text = TRIM(SUBSTRING(remaining_text, space_pos + 1));
        END IF;

        IF word_text <> '' THEN
            IF result_text <> '' THEN
                SET result_text = CONCAT(result_text, ' ');
            END IF;

            SET result_text = CONCAT(
                result_text,
                UPPER(LEFT(word_text, 1)),
                SUBSTRING(word_text, 2)
            );
        END IF;
    END WHILE;

    RETURN result_text;
END$$

DELIMITER ;

